sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 q=coord/scale;float2 cell=floor(q);float n=hash(cell);float y=fract(q.y+phase*(0.3+n));float x=fract(q.x+sin(phase+n*6.28)*0.15);float d=length(float2(x-0.5,y-0.5));float sizep=0.04+0.08*n;float m=(1.0-smoothstep(sizep,sizep+0.04,d))*step(1.0-amount,n);return half4(clamp(c.rgb+tint.rgb*half(m)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
